"use client";
import {useEffect,useState} from "react";
import {api} from "@/lib/api-client";

type Campaign={id:string;productId:string;name:string;slug:string;launchAt:string;status:string;homepage:boolean;flashDealId:string|null;launchedAt:string|null};
export default function LaunchCampaignsPage(){const[c,setC]=useState<Campaign[]>([]);const[products,setProducts]=useState<any[]>([]);const[productId,setProductId]=useState("");const[launchAt,setLaunchAt]=useState("");const[homepage,setHomepage]=useState(true);const[busy,setBusy]=useState(false);const load=()=>{api.get<{campaigns:Campaign[]}>('/api/launch-campaigns/mine').then(r=>setC(r.campaigns)).catch(()=>setC([]));api.get<any>('/api/products/mine').then(r=>setProducts(r.products??r)).catch(()=>setProducts([]));};useEffect(load,[]);const create=async()=>{if(!productId||!launchAt)return;setBusy(true);try{await api.post('/api/launch-campaigns',{productId,launchAt:new Date(launchAt).toISOString(),homepage});setProductId('');setLaunchAt('');load();}finally{setBusy(false);}};const action=async(id:string,type:'launch'|'cancel')=>{await api.post(`/api/launch-campaigns/${id}/${type}`,{});load();};return <div className="shell py-8"><h1 className="text-xl font-bold text-graphite-900">Launch campaigns</h1><p className="mt-1 text-sm text-graphite-600">Schedule a product launch and optionally place it on the TTFL Store homepage.</p><div className="mt-6 rounded-card border border-graphite-200 p-5"><h2 className="font-semibold">Schedule a launch</h2><div className="mt-4 grid gap-3 sm:grid-cols-3"><select value={productId} onChange={e=>setProductId(e.target.value)} className="rounded-card border border-graphite-300 px-3 py-2"><option value="">Select product</option>{products.filter(p=>p.status==='ACTIVE'&&!p.comingSoon).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><input type="datetime-local" value={launchAt} onChange={e=>setLaunchAt(e.target.value)} className="rounded-card border border-graphite-300 px-3 py-2"/><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={homepage} onChange={e=>setHomepage(e.target.checked)}/> Homepage placement</label></div><button disabled={busy||!productId||!launchAt} onClick={create} className="mt-4 rounded-card bg-ember-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50">{busy?'Scheduling…':'Schedule launch'}</button></div><div className="mt-8"><h2 className="mb-3 text-sm font-bold uppercase tracking-wide text-graphite-600">Campaigns</h2><div className="flex flex-col gap-2">{c.length===0?<p className="text-sm text-graphite-600">No launch campaigns yet.</p>:c.map(x=><div key={x.id} className="flex flex-col gap-3 rounded-card border border-graphite-200 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-semibold">{x.name}</p><p className="text-sm text-graphite-600">{new Date(x.launchAt).toLocaleString()} · {x.status}{x.homepage?' · Homepage':''}</p></div>{x.status==='SCHEDULED'&&<div className="flex gap-2"><button onClick={()=>action(x.id,'launch')} className="rounded-card bg-ember-600 px-3 py-2 text-sm font-semibold text-white">Launch now</button><button onClick={()=>action(x.id,'cancel')} className="rounded-card border border-graphite-300 px-3 py-2 text-sm font-semibold">Cancel</button></div>}</div>)}</div></div></div>}
